<?php
namespace App\Core\Connectors\Drivers;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Connectors\DTO\{ConnectorAction,ConnectorResult};use App\Models\ConnectorConnection;
final class CalendlyConnector extends AbstractConnector {public function id():string{return 'calendly';}public function label():string{return 'Calendly';}public function actions():array{return [new ConnectorAction('me','Get the authenticated Calendly user.',RiskLevel::Read),new ConnectorAction('scheduled_events','List scheduled events using supplied query parameters.',RiskLevel::Read,['type'=>'object','properties'=>['organization'=>['type'=>'string'],'user'=>['type'=>'string'],'min_start_time'=>['type'=>'string'],'max_start_time'=>['type'=>'string']]]),new ConnectorAction('create_scheduling_link','Create a single-use scheduling link for an event type.',RiskLevel::ExternalWrite,['type'=>'object','properties'=>['max_event_count'=>['type'=>'integer'],'owner'=>['type'=>'string'],'owner_type'=>['type'=>'string']],'required'=>['owner','owner_type']])];}public function configurationSchema():array{return ['credentials'=>['access_token'=>['type'=>'password','required'=>true]],'fields'=>[]];}private function req(ConnectorConnection $c){return $this->client(['Authorization'=>'Bearer '.$this->bearer($c,'access_token')]);}public function test(ConnectorConnection $c):bool{try{return $this->req($c)->get('https://api.calendly.com/users/me')->successful();}catch(\Throwable){return false;}}public function execute(ConnectorConnection $c,string $action,array $a):ConnectorResult{$this->action($action);return match($action){'me'=>ConnectorResult::success($this->req($c)->get('https://api.calendly.com/users/me')->throw()->json()),'scheduled_events'=>ConnectorResult::success($this->req($c)->get('https://api.calendly.com/scheduled_events',$a)->throw()->json()),'create_scheduling_link'=>ConnectorResult::success($this->req($c)->post('https://api.calendly.com/scheduling_links',$a)->throw()->json()),default=>ConnectorResult::failure('Unsupported action')};}}
